package org.slavicmyths.verify;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.gametest.*;
import org.slavicmyths.poloz.*;
import org.slavicmyths.rpg.Runes;
@GameTestHolder("slavicmyths_poloz") @PrefixGameTestTemplate(false)
public final class PolozRewardTests {
 @GameTest(template="empty",timeoutTicks=30,batch="poloz_rewards") public static void upgradeComponents(GameTestHelper t){
  var p=MorExposureTests.player(t);var s=new ItemStack(Items.NETHERITE_CHESTPLATE);s.setDamageValue(37);s.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Preserved"));var tag=new net.minecraft.nbt.CompoundTag();tag.putString("foreign","keep");s.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(tag));Runes.write(s,2,java.util.List.of("earth_heart_iii"));var enchant=t.getLevel().registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getHolderOrThrow(net.minecraft.world.item.enchantment.Enchantments.PROTECTION);s.enchant(enchant,4);var result=PolozRewards.upgradeCopy(s);
  t.assertTrue(result.is(PolozRewards.ARMOR.get(EquipmentSlot.CHEST).get())&&result.getDamageValue()==37,"piece and durability");t.assertTrue(result.getComponentsPatch().equals(s.getComponentsPatch()),"all enchantment, rune and foreign components preserved");t.assertTrue(PolozRewards.upgradeCopy(new ItemStack(Items.DIAMOND_CHESTPLATE)).isEmpty(),"netherite only");p.discard();t.succeed();
 }
 @GameTest(template="empty",timeoutTicks=30,batch="poloz_rewards") public static void armorAndGround(GameTestHelper t){var p=MorExposureTests.player(t);for(var slot:PolozRewards.ARMOR.keySet())p.setItemSlot(slot,new ItemStack(PolozRewards.ARMOR.get(slot).get()));PolozRewardEvents.refresh(p);t.assertTrue(Math.abs(p.getMaxHealth()-34)<.001,"exactly fourteen health from complete set");t.assertTrue(Math.abs(PolozRewards.reduction(p)-.22)<.0001&&Math.abs(PolozRewards.knockback(p)-.55)<.0001,"additive parts");t.setBlock(new BlockPos(4,1,4),org.slavicmyths.mor.MorBlocks.BLOCKS.get("dirt").get());float health=p.getHealth();for(int i=1;i<12;i++)MorExposureTests.sample(p,i);t.assertTrue(p.getHealth()==health&&!p.hasEffect(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN),"actual infected-ground immunity");p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);PolozRewardEvents.refresh(p);t.assertTrue(p.getMaxHealth()==20&&!PolozRewards.full(p),"set bonus removed");for(int i=12;i<18;i++)MorExposureTests.sample(p,i);t.assertTrue(p.hasEffect(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN),"exposure resumes after removing helmet");p.discard();t.succeed();}
 @GameTest(template="empty",timeoutTicks=30,batch="poloz_rewards") public static void smithCost(GameTestHelper t){var p=MorExposureTests.player(t);var pos=t.absolutePos(new BlockPos(4,1,4));t.getLevel().setBlock(pos,Blocks.SMITHING_TABLE.defaultBlockState(),3);p.setShiftKeyDown(true);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.NETHERITE_BOOTS));p.getInventory().setItem(5,new ItemStack(PolozContent.SCALE.get()));var hit=new net.minecraft.world.phys.BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false);PolozRewardEvents.smith(new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock(p,net.minecraft.world.InteractionHand.MAIN_HAND,pos,hit));t.assertTrue(p.getMainHandItem().is(Items.NETHERITE_BOOTS)&&p.getInventory().getItem(5).getCount()==1,"insufficient material no mutation");p.getInventory().getItem(5).grow(2);PolozRewardEvents.smith(new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock(p,net.minecraft.world.InteractionHand.MAIN_HAND,pos,hit));t.assertTrue(p.getMainHandItem().is(PolozRewards.ARMOR.get(EquipmentSlot.FEET).get())&&p.getInventory().getItem(5).getCount()==1,"exactly two scales spent");p.discard();t.succeed();}
 @GameTest(template="empty",timeoutTicks=30,batch="poloz_rewards") public static void runeSockets(GameTestHelper t){var whip=new ItemStack(PolozRewards.WHIP.get());Runes.write(whip,2,java.util.List.of());var inv=new net.minecraft.world.SimpleContainer(whip,new ItemStack(PolozRewards.RUNE.get()));t.assertTrue(Runes.installationBlocker(whip,inv.getItem(1))==null,"native socket admission");var installed=Runes.preview(inv,1);t.assertTrue(Runes.has(installed,"earth_lord_iv"),"native socket result");t.assertTrue(!Runes.compatible(new ItemStack(Items.NETHERITE_CHESTPLATE),"earth_lord_iv"),"weapon-only rune");var saved=installed.save(t.getLevel().registryAccess());var loaded=ItemStack.parseOptional(t.getLevel().registryAccess(),(net.minecraft.nbt.CompoundTag)saved);t.assertTrue(Runes.has(loaded,"earth_lord_iv"),"rune component serialization");t.succeed();}
 @GameTest(template="empty",timeoutTicks=30,batch="poloz_rewards") public static void spikeLifetime(GameTestHelper t){var p=MorExposureTests.player(t);for(int x=2;x<8;x++)for(int z=4;z<12;z++)t.setBlock(new BlockPos(x,1,z),Blocks.STONE);p.setYRot(0);PolozRewardEvents.spikes(p);var spikes=t.getLevel().getEntitiesOfClass(PolozStoneSpike.class,p.getBoundingBox().inflate(8));t.assertTrue(spikes.size()==3,"three visible native spike entities");t.runAtTickTime(26,()->{t.assertTrue(spikes.stream().allMatch(Entity::isRemoved),"short lived effects");t.assertTrue(t.getBlockState(new BlockPos(4,1,6)).is(Blocks.STONE),"no terrain destruction");p.discard();t.succeed();});}
 @GameTest(template="empty",timeoutTicks=40,batch="poloz_rewards") public static void fourthAcceptedHit(GameTestHelper t){var p=MorExposureTests.player(t);var sword=new ItemStack(Items.NETHERITE_SWORD);Runes.write(sword,2,java.util.List.of("earth_lord_iv"));p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,sword);var cow=EntityType.COW.create(t.getLevel());cow.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);cow.setHealth(200);cow.setNoAi(true);cow.moveTo(p.position().add(0,0,1));t.getLevel().addFreshEntity(cow);for(int i=1;i<=8;i++){final int index=i;t.runAtTickTime(i*2,()->{cow.invulnerableTime=0;t.assertTrue(cow.hurt(p.damageSources().playerAttack(p),1),"accepted primary hit "+index);if(index==4)t.assertTrue(Math.abs(cow.getHealth()-190)<.001,"fourth hit adds exactly six damage");if(index==8){t.assertTrue(Math.abs(cow.getHealth()-186)<.001,"second fourth hit suppressed by 20-second cooldown");t.assertTrue(p.getPersistentData().getInt("PolozRuneHits")==0,"secondary fissure did not increment counter");cow.discard();p.discard();t.succeed();}});}}
 @GameTest(template="empty",timeoutTicks=30,batch="poloz_rewards") public static void bossRewards(GameTestHelper t){var b=PolozGameTests.boss(t);b.die(b.damageSources().generic());var drops=t.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,b.getBoundingBox().inflate(4));for(var item:new Item[]{PolozContent.CORE.get(),PolozRewards.WHIP.get(),PolozTrophy.ITEM.get()})t.assertTrue(drops.stream().filter(e->e.getItem().is(item)).mapToInt(e->e.getItem().getCount()).sum()==1,"guaranteed singleton reward "+item);int scales=drops.stream().filter(e->e.getItem().is(PolozContent.SCALE.get())).mapToInt(e->e.getItem().getCount()).sum();t.assertTrue(scales>=8&&scales<=12,"guaranteed scale range");b.die(b.damageSources().generic());t.assertTrue(t.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,b.getBoundingBox().inflate(4)).stream().filter(e->e.getItem().is(PolozRewards.WHIP.get())).count()==1,"no repeated reward");b.discard();var d=PolozEvent.get(t.getLevel());d.state=PolozEvent.State.IDLE;d.boss=null;d.cooldownUntil=0;d.setDirty();t.succeed();}
 @GameTest(template="empty",timeoutTicks=30,batch="poloz_rewards") public static void trophySingleDrop(GameTestHelper t){var w=t.getLevel();var pos=t.absolutePos(new BlockPos(8,2,8));var state=PolozTrophy.BLOCK.get().defaultBlockState().setValue(PolozTrophy.FACING,Direction.SOUTH);w.setBlock(pos,state,3);((PolozTrophy)PolozTrophy.BLOCK.get()).setPlacedBy(w,pos,state,null,new ItemStack(PolozTrophy.ITEM.get()));int count=0;for(int i=0;i<36;i++)if(w.getBlockState(pos.offset(PolozTrophy.offset(Direction.SOUTH,i))).is(PolozTrophy.BLOCK.get()))count++;t.assertTrue(count==36,"3x3x4 occupancy");w.destroyBlock(pos.offset(PolozTrophy.offset(Direction.SOUTH,35)),true);t.assertTrue(w.getBlockState(pos).isAir(),"breaking side removes anchor");var drops=w.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(pos).inflate(5),e->e.getItem().is(PolozTrophy.ITEM.get()));t.assertTrue(drops.stream().mapToInt(e->e.getItem().getCount()).sum()==1,"one trophy for 36 cells");t.succeed();}
}
